pub struct CognitiveToolRegistry;

impl CognitiveToolRegistry {
    pub async fn register_all(
        registry: &ToolRegistry,
        store: Arc<CognitiveMemoryStore>,
    ) -> Result<()> {
        registry
            .register(Arc::new(MemoryTool::new(store.clone())) as BoxedTool)
